 $r=$queue->result($session,$id);check(($r['body']['state']??'')===$receipt['state'],$kind.' Public result matches canonical Local state');
 return ['receipt'=>$receipt,'envelope'=>$request,'ack'=>$ack,'result'=>$r,'client_envelope'=>$e];
};
